function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 500) return 's needs 1 to 500 characters.';
  if (!/^[01]+$/.test(s)) return 's may contain only 0 and 1.';
  if (s[0] !== '1') return 's must start with 1.';
  return null;
}

