function generate(rand, size) {
  const n = size === 'large' ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 12);
  const style = rand();
  let s = '1';
  for (let i = 1; i < n; i++) {
    if (style < 0.15) s += '1';
    else if (style < 0.25) s += '0';
    else s += rand() < 0.5 ? '1' : '0';
  }
  return [s];
}
